#!/bin/bash
set -e
cd ~/freddy-fixit
echo "Writing 7 files..."
mkdir -p "$(dirname "src/components/ContractorProfileCompletion.tsx")"
base64 -d > 'src/components/ContractorProfileCompletion.tsx' <<'B64_EOF'

B64_EOF
mkdir -p "$(dirname "src/pages/ContractorDashboard.tsx")"
base64 -d > 'src/pages/ContractorDashboard.tsx' <<'B64_EOF'

B64_EOF
mkdir -p "$(dirname "src/pages/ClientDashboard.tsx")"
base64 -d > 'src/pages/ClientDashboard.tsx' <<'B64_EOF'

B64_EOF
mkdir -p "$(dirname "src/pages/AdminDashboard.tsx")"
base64 -d > 'src/pages/AdminDashboard.tsx' <<'B64_EOF'

B64_EOF
mkdir -p "$(dirname "supabase/migrations/20260805120000_refire_stale_requests.sql")"
base64 -d > 'supabase/migrations/20260805120000_refire_stale_requests.sql' <<'B64_EOF'

B64_EOF
mkdir -p "$(dirname "supabase/migrations/20260805120100_escalate_uses_specialty_map.sql")"
base64 -d > 'supabase/migrations/20260805120100_escalate_uses_specialty_map.sql' <<'B64_EOF'

B64_EOF
mkdir -p "$(dirname "CLAUDE.md")"
base64 -d > 'CLAUDE.md' <<'B64_EOF'

B64_EOF

echo "Building (this is the real check — it stops the script if anything is wrong)..."
npx vite build

git add -A
git commit -m "Re-fire stalled job requests automatically at 24h and 48h, plus contractor profile photos" || true
git push
echo ""
echo "OK - pushed. Vercel is deploying now. Hard-refresh in about a minute (Cmd+Shift+R)."
